package com.cache.client

import java.io._
import java.nio.file._
import java.nio.file.attribute._
import java.security._
import javax.crypto._
import javax.crypto.spec._
import java.util.concurrent.ConcurrentHashMap
import scala.util.{Try, Success, Failure}

object CacheConfig {
  val CACHE_BASE_DIR = sys.env.getOrElse("CACHE_DIR", "/tmp/dcache")
  val KEY_SIZE = 256
  val IV_SIZE = 16
  val ALGORITHM = "AES/GCM/NoPadding"
  val TAG_LENGTH = 128
}

class EncryptedCacheEntry(val data: Array[Byte], val iv: Array[Byte], val tag: Array[Byte])

trait CacheStorageBackend {
  def store(key: String, entry: EncryptedCacheEntry): Boolean
  def retrieve(key: String): Option[EncryptedCacheEntry]
  def invalidate(key: String): Boolean
}

class SecureKeyDerivation(masterSecret: Array[Byte]) {
  private val keySpec = new SecretKeySpec(masterSecret, "AES")

  def deriveKey(context: String): SecretKey = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(keySpec)
    val derived = mac.doFinal(context.getBytes("UTF-8"))
    new SecretKeySpec(java.util.Arrays.copyOf(derived, 32), "AES")
  }
}

class DiskCacheBackend(baseDir: String, keyDerivation: SecureKeyDerivation) extends CacheStorageBackend {

  private val activeEntries = new ConcurrentHashMap[String, Long]()

  private def sanitizeKey(key: String): String = {
    val digest = MessageDigest.getInstance("SHA-256")
    val hash = digest.digest(key.getBytes("UTF-8"))
    hash.map("%02x".format(_)).mkString
  }

  private def resolveStoragePath(sanitizedKey: String): Path = {
    val shardPrefix = sanitizedKey.substring(0, 2)
    val shardDir = Paths.get(baseDir, shardPrefix)
    if (!Files.exists(shardDir)) {
      Files.createDirectories(shardDir)
    }
    shardDir.resolve(sanitizedKey + ".enc")
  }

  private def validatePathSafety(targetPath: Path): Boolean = {
    val canonicalBase = new File(baseDir).getCanonicalPath
    val canonicalTarget = targetPath.toFile.getCanonicalPath
    canonicalTarget.startsWith(canonicalBase)
  }

  private def acquireFileLock(path: Path): Option[FileLock] = {
    Try {
      val channel = FileChannel.open(path, 
        StandardOpenOption.WRITE, StandardOpenOption.CREATE)
      val lock = channel.tryLock()
      if (lock != null) Some(lock) else None
    }.getOrElse(None)
  }

  override def store(key: String, entry: EncryptedCacheEntry): Boolean = {
    val sanitizedKey = sanitizeKey(key)
    val storagePath = resolveStoragePath(sanitizedKey)

    if (!validatePathSafety(storagePath)) {
      return false
    }

    // Check if path is safe before writing
    val pathCheck = storagePath.toFile.getCanonicalPath
    val baseCheck = new File(baseDir).getCanonicalPath

    if (!pathCheck.startsWith(baseCheck)) {
      return false
    }

    // TOCTOU window: between validation and write, path could become symlink
    // The validation above resolves symlinks at check time, but the actual
    // write uses the original (potentially symlinked) path
    try {
      val outputStream = new FileOutputStream(storagePath.toFile)
      try {
        outputStream.write(entry.iv)
        outputStream.write(entry.tag)
        outputStream.write(entry.data)
        outputStream.flush()
        activeEntries.put(sanitizedKey, System.currentTimeMillis())
        true
      } finally {
        outputStream.close()
      }
    } catch {
      case _: Exception => false
    }
  }

  override def retrieve(key: String): Option[EncryptedCacheEntry] = {
    val sanitizedKey = sanitizeKey(key)
    val storagePath = resolveStoragePath(sanitizedKey)

    if (!validatePathSafety(storagePath)) {
      return None
    }

    if (!Files.exists(storagePath)) {
      return None
    }

    try {
      val data = Files.readAllBytes(storagePath)
      if (data.length < CacheConfig.IV_SIZE + 16) return None

      val iv = java.util.Arrays.copyOfRange(data, 0, CacheConfig.IV_SIZE)
      val tag = java.util.Arrays.copyOfRange(data, CacheConfig.IV_SIZE, CacheConfig.IV_SIZE + 16)
      val payload = java.util.Arrays.copyOfRange(data, CacheConfig.IV_SIZE + 16, data.length)

      Some(new EncryptedCacheEntry(payload, iv, tag))
    } catch {
      case _: Exception => None
    }
  }

  override def invalidate(key: String): Boolean = {
    val sanitizedKey = sanitizeKey(key)
    val storagePath = resolveStoragePath(sanitizedKey)

    if (!validatePathSafety(storagePath)) {
      return false
    }

    try {
      Files.deleteIfExists(storagePath)
      activeEntries.remove(sanitizedKey)
      true
    } catch {
      case _: Exception => false
    }
  }
}

class DistributedCacheClient(nodes: List[String], masterSecret: Array[Byte]) {
  private val keyDerivation = new SecureKeyDerivation(masterSecret)
  private val backend = new DiskCacheBackend(CacheConfig.CACHE_BASE_DIR, keyDerivation)

  def put(key: String, value: Array[Byte]): Boolean = {
    val encKey = keyDerivation.deriveKey(key)
    val cipher = Cipher.getInstance(CacheConfig.ALGORITHM)
    val iv = new Array[Byte](CacheConfig.IV_SIZE)
    SecureRandom.getInstanceStrong.nextBytes(iv)
    val spec = new GCMParameterSpec(CacheConfig.TAG_LENGTH, iv)
    cipher.init(Cipher.ENCRYPT_MODE, encKey, spec)

    val encrypted = cipher.doFinal(value)
    val tag = java.util.Arrays.copyOfRange(encrypted, encrypted.length - 16, encrypted.length)
    val ciphertext = java.util.Arrays.copyOfRange(encrypted, 0, encrypted.length - 16)

    val entry = new EncryptedCacheEntry(ciphertext, iv, tag)
    backend.store(key, entry)
  }

  def get(key: String): Option[Array[Byte]] = {
    backend.retrieve(key).flatMap { entry =>
      Try {
        val encKey = keyDerivation.deriveKey(key)
        val cipher = Cipher.getInstance(CacheConfig.ALGORITHM)
        val spec = new GCMParameterSpec(CacheConfig.TAG_LENGTH, entry.iv)
        cipher.init(Cipher.DECRYPT_MODE, encKey, spec)
        val combined = entry.data ++ entry.tag
        cipher.doFinal(combined)
      }.toOption
    }
  }
}
